+// RF-006: regla de auditoría EMBA para todo motivo de anulación, ajuste o corrección:
+// al menos 10 caracteres sin contar los espacios de los bordes. Devuelve el motivo recortado.
+export const MOTIVO_MIN_CARACTERES = 10;
+export function validarMotivo(motivo) {
+  const limpio = typeof motivo === "string" ? motivo.trim() : "";
+  if (limpio.length < MOTIVO_MIN_CARACTERES)
+    throw new Error(`El motivo es obligatorio y debe tener al menos ${MOTIVO_MIN_CARACTERES} caracteres`);
+  return limpio;
+}
+
+// RF-005: anula una factura emitida. No altera la original (ADR-002): devuelve una factura nueva y congelada.
+export function anularFactura(factura, motivo) {
+  if (factura?.estado !== "emitida") throw new Error("Solo se puede anular una factura emitida");
+  return Object.freeze({ ...factura, estado: "anulada", motivo: validarMotivo(motivo) });
+}
